function averageValue(nums) {
  const picked = nums.filter(v => v % 2 === 0 && v % 3 === 0);
  if (picked.length === 0) return 0;
  const total = picked.reduce((acc, v) => acc + v, 0);
  let average = 0;
  while ((average + 1) * picked.length <= total) average++;
  return average;
}

