function generate(rand, size) {
  const n = size === 'large' ? 1000 : 1 + Math.floor(rand() * 8);
  const high = size === 'large' ? 1000 : 40;
  // Mix in plenty of multiples of 6 so averages are usually non-zero.
  const share = rand();
  const nums = Array.from({ length: n }, () => {
    if (rand() < share) return 6 * (1 + Math.floor(rand() * Math.floor(high / 6)));
    return 1 + Math.floor(rand() * high);
  });
  return [nums];
}
